-- Webhook delivery dedupe. Event keys do not expire. Account keys refresh after the window.
-- Do not edit this file after it ships; add a new migration instead.

CREATE TABLE webhook_dedupe (
  key text PRIMARY KEY,
  kind text NOT NULL,
  account_id text,
  run_id text,
  seen_at timestamptz NOT NULL
);

CREATE INDEX webhook_dedupe_account_idx ON webhook_dedupe (account_id, seen_at);
